-- Migration 003: Content and media
CREATE TYPE content_visibility AS ENUM ('PUBLIC','SUBSCRIBERS_ONLY','TIER_RESTRICTED','PPV_ONLY');
CREATE TYPE media_processing_status AS ENUM ('UPLOADING','SCANNING','PROCESSING','READY','FAILED','QUARANTINED');
CREATE TYPE media_type AS ENUM ('IMAGE','VIDEO','AUDIO');
CREATE TABLE content_posts (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), creator_id UUID NOT NULL REFERENCES creator_profiles(id) ON DELETE RESTRICT, title VARCHAR(255), text_content TEXT, visibility content_visibility NOT NULL DEFAULT 'SUBSCRIBERS_ONLY', required_tier_level INT DEFAULT 1, is_ppv BOOLEAN NOT NULL DEFAULT FALSE, ppv_price_cents BIGINT DEFAULT 0 CHECK(ppv_price_cents>=0), compliance_2257_id UUID REFERENCES performer_records_2257(id), is_published BOOLEAN NOT NULL DEFAULT FALSE, published_at TIMESTAMPTZ, likes_count INT NOT NULL DEFAULT 0, comments_count INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE media_assets (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), post_id UUID REFERENCES content_posts(id) ON DELETE CASCADE, creator_id UUID NOT NULL REFERENCES creator_profiles(id), media_type media_type NOT NULL, original_file_name VARCHAR(255) NOT NULL, storage_bucket VARCHAR(100) NOT NULL, storage_key TEXT NOT NULL, hls_manifest_key TEXT, thumbnail_key TEXT, blur_hash VARCHAR(100), duration_seconds INT DEFAULT 0, width INT, height INT, file_size_bytes BIGINT NOT NULL, phash_signature VARCHAR(128), sha256_checksum VARCHAR(64) NOT NULL, processing_status media_processing_status NOT NULL DEFAULT 'UPLOADING', is_flagged_for_review BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
